#[test]
fn module_evaluate_with_cancelled_handle_returns_rejected_promise() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("module reason"));

    let module =
        Module::parse(Source::from_bytes("export let x = 1;"), None, &mut context).unwrap();

    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .expect("evaluate_with_evaluation must return Ok for an already-cancelled handle");
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("module reason")))
    );
}

